<?php require_once __DIR__.'/../app/App.php'; Auth::requirePlatform(); $api=AppContext::api(); $error=''; try{if($_SERVER['REQUEST_METHOD']==='POST'){Auth::platformApi($api,'PATCH','/api/v1/platform/tenants/'.(int)$_POST['id'].'/status',['status'=>$_POST['status']]);} $data=Auth::platformApi($api,'GET','/api/v1/platform/tenants');$tenants=$data['tenants']??[];}catch(Throwable $e){$error=$e->getMessage();$tenants=[];} ?><!doctype html><html><head><meta charset="utf-8"><title>Platform Tenants</title><style>body{font-family:Arial;background:#f5f6f8;margin:0;padding:30px}main{max-width:1000px;margin:auto;background:#fff;padding:25px;border-radius:12px}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}button{padding:7px 10px;border:0;border-radius:5px;cursor:pointer}.active{background:#d1fadf}.suspended{background:#fee4e2}.err{color:#b42318}</style></head><body><main><h1>Tenants</h1><p>Manage organizations on PassNow.</p><?php if($error):?><p class="err"><?=htmlspecialchars($error)?></p><?php endif?><table><tr><th>Organization</th><th>Slug</th><th>Status</th><th>Created</th><th>Action</th></tr><?php foreach($tenants as $t):?><tr><td><?=htmlspecialchars($t['name'])?></td><td><?=htmlspecialchars($t['slug'])?></td><td><span class="<?=htmlspecialchars($t['status'])?>"><?=htmlspecialchars($t['status'])?></span></td><td><?=htmlspecialchars((string)$t['created_at'])?></td><td><form method="post"><input type="hidden" name="id" value="<?= (int)$t['id']?>"><?php if($t['status']==='active'):?><input type="hidden" name="status" value="suspended"><button>Suspend</button><?php else:?><input type="hidden" name="status" value="active"><button>Activate</button><?php endif?></form></td></tr><?php endforeach?></table></main></body></html>